import math
import numpy as np
from scipy.integrate import solve_ivp

def compare_solvers():
    A = np.array([[-0.5, 0.0], [50.0, -50.0]]); c = np.array([0.02, 0.0])
    out = {}
    for m in ('RK45', 'Radau', 'BDF'):
        s = solve_ivp(lambda t, y: A @ y + c, [0, 10], [0.06, 0.03], method=m, rtol=1e-6, atol=1e-9)
        out[m] = (int(s.nfev), float(s.y[1, -1]))
    return out
